function validate([words]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 100000) return 'words needs 1 to 10^5 strings.';
  let total = 0;
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1) return 'Every word has at least one letter.';
    if (!/^[a-z]+$/.test(word)) return 'Words use only lowercase English letters.';
    total += word.length;
  }
  if (total > 100000) return 'The words may hold at most 10^5 letters in total.';
  return null;
}

