function longestWord(words) {
  const root = { children: {}, isWord: false };
  for (const word of words) {
    let node = root;
    for (const ch of word) {
      if (!node.children[ch]) {
        node.children[ch] = { children: {}, isWord: false };
      }
      node = node.children[ch];
    }
    node.isWord = true;
  }
  let best = '';
  for (const word of words) {
    if (word.length < best.length || (word.length === best.length && word >= best)) {
      continue;
    }
    let node = root;
    let complete = true;
    for (const ch of word) {
      node = node.children[ch];
      if (!node.isWord) {
        complete = false;
        break;
      }
    }
    if (complete) {
      best = word;
    }
  }
  return best;
}

