function generate(rand, size) {
  const large = size === 'large';
  const alphabet = large ? 'abcde' : (rand() < 0.5 ? 'ab' : 'abc');
  const letter = () => alphabet[Math.floor(rand() * alphabet.length)];
  const target = large ? 1800 : 1 + Math.floor(rand() * 8);
  const maxLength = large ? 12 : 4;
  const words = [];
  let total = 0;
  while (words.length < target && total < 9000) {
    let word;
    if (words.length > 0 && rand() < 0.7) {
      const base = words[Math.floor(rand() * words.length)];
      word = base.length < maxLength ? base + letter() : base;
    } else {
      const len = 1 + Math.floor(rand() * (large ? 6 : 3));
      word = Array.from({ length: len }, letter).join('');
    }
    words.push(word);
    total += word.length;
  }
  for (let i = words.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [words[i], words[j]] = [words[j], words[i]];
  }
  return [words];
}
